const services=[{id:'corte',icon:'✂',name:'Corte & escova',description:'Leveza, movimento e um novo olhar para você.',duration:60,price:100},{id:'coloracao',icon:'◈',name:'Coloração',description:'Tons que iluminam e revelam sua personalidade.',duration:120,price:180},{id:'tratamento',icon:'✧',name:'Hidratação',description:'Um ritual de nutrição e brilho para seus fios.',duration:60,price:80},{id:'unhas',icon:'❀',name:'Manicure',description:'Cuidado e delicadeza até a ponta dos dedos.',duration:60,price:35}];
const $=id=>document.getElementById(id), money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}), key='jaiane-neves-bookings-v1';
let selectedTime='',storageAvailable=true;
function readBookings(){try{const data=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(data)?data.filter(b=>b&&typeof b.id==='string'&&typeof b.date==='string'&&Number.isFinite(b.duration)&&typeof b.time==='string'):[]}catch{return []}}
function saveBookings(data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{storageAvailable=false;$('formStatus').textContent='Não foi possível salvar. Verifique se o armazenamento do navegador está habilitado.';return false}}
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const minutes=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);
function currentService(){return services.find(s=>s.id===$('service').value)}
function available(time){const date=$('date').value,s=currentService(),start=minutes(time),now=new Date();if(!date||date<localDate()||new Date(date+'T12:00:00').getDay()===0)return false;if(date===localDate()&&start<=now.getHours()*60+now.getMinutes())return false;if(start+s.duration>1080)return false;return !readBookings().some(b=>b.date===date&&start<minutes(b.time)+b.duration&&start+s.duration>minutes(b.time))}
function renderTimes(){selectedTime='';$('times').replaceChildren();const date=$('date').value;if(!date){$('timeHint').textContent='Selecione uma data para ver os horários.';return}if(new Date(date+'T12:00:00').getDay()===0){$('timeHint').textContent='Domingo é dia de pausa. Escolha de segunda a sábado.';return}let count=0;for(let hour=9;hour<18;hour++){const time=`${String(hour).padStart(2,'0')}:00`,button=document.createElement('button');button.type='button';button.className='time';button.textContent=time;button.disabled=!available(time);button.setAttribute('aria-pressed','false');if(!button.disabled)count++;button.onclick=()=>{document.querySelectorAll('.time').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});button.classList.add('selected');button.setAttribute('aria-pressed','true');selectedTime=time;$('formStatus').textContent=''};$('times').append(button)}$('timeHint').textContent=count?'Horários demonstrativos · Atendimento das 9h às 18h.':'Sem horários disponíveis nesta data. Escolha outro dia.'}
function updateService(){const s=currentService();$('duration').textContent=`◷ Duração estimada: ${s.duration} min`;$('price').textContent=money(s.price);renderTimes()}
services.forEach(s=>{const option=document.createElement('option');option.value=s.id;option.textContent=s.name;$('service').append(option);const card=document.createElement('button');card.type='button';card.className='service-card';card.innerHTML=`<span class="service-icon" aria-hidden="true">${s.icon}</span><h3>${s.name}</h3><p>${s.description}</p><div class="service-bottom"><strong>${money(s.price)}</strong><span>${s.duration} min ↗</span></div>`;card.onclick=()=>{$('service').value=s.id;updateService();$('agendar').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};$('services').append(card)});
$('date').min=localDate();$('year').textContent=new Date().getFullYear();$('date').addEventListener('change',renderTimes);$('service').addEventListener('change',updateService);updateService();
$('phone').addEventListener('input',e=>{const v=e.target.value.replace(/\D/g,'').slice(0,11);e.target.value=v.length>6?`(${v.slice(0,2)}) ${v.slice(2,-4)}-${v.slice(-4)}`:v.length>2?`(${v.slice(0,2)}) ${v.slice(2)}`:v});
$('bookingForm').addEventListener('submit',e=>{e.preventDefault();const status=$('formStatus');if(!$('name').value.trim()||$('phone').value.replace(/\D/g,'').length<10){status.textContent='Preencha seu nome e um telefone válido com DDD.';return}if(!selectedTime){status.textContent='Escolha um horário disponível.';return}if(!available(selectedTime)){status.textContent='Esse horário não está mais disponível. Escolha outro.';renderTimes();return}const s=currentService(),booking={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),service:s.name,duration:s.duration,price:s.price,date:$('date').value,time:selectedTime,name:$('name').value.trim(),phone:$('phone').value};if(!saveBookings([...readBookings(),booking]))return;renderTimes();status.textContent=`Reserva salva neste navegador! ${booking.service}, ${new Date(booking.date+'T12:00:00').toLocaleDateString('pt-BR')}, às ${booking.time}. Ela não foi enviada ao salão.`;});
function renderBookings(){const list=$('bookingList');list.replaceChildren();const bookings=readBookings().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));if(!bookings.length){const p=document.createElement('p');p.className='hint';p.textContent='Você ainda não tem reservas neste navegador.';list.append(p)}bookings.forEach(b=>{const article=document.createElement('article');article.className='saved-booking';const title=document.createElement('strong');title.textContent=b.service;const detail=document.createElement('p');detail.textContent=`${new Date(b.date+'T12:00:00').toLocaleDateString('pt-BR')} às ${b.time} · ${b.name} · ${money(b.price)}`;const cancel=document.createElement('button');cancel.className='cancel';cancel.textContent='Cancelar reserva';cancel.onclick=()=>{if(confirm('Deseja cancelar esta reserva local?')&&saveBookings(readBookings().filter(x=>x.id!==b.id))){renderBookings();renderTimes()}};article.append(title,detail,cancel);list.append(article)})}
$('myBookings').onclick=()=>{renderBookings();$('bookingsDialog').showModal()};$('closeDialog').onclick=()=>$('bookingsDialog').close();$('bookingsDialog').addEventListener('click',e=>{if(e.target===$('bookingsDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});window.addEventListener('storage',e=>{if(e.key===key){renderTimes();if($('bookingsDialog').open)renderBookings()}});
